// Moby state machine: wait, check hit on first probe, then clean up and delete.
void update_moby_hit_removal_state(char *m) {
    int hit = 0;
    char *r = MobyGetHitMessage(m, 0x10000, 0);
    switch (*(unsigned char *)(m + 0x20)) {
    case 0:
        m[0x20] = 1;
        break;
    case 1:
        if (r != 0 && *(float *)(r + 0x2C) > 0.0f) hit = 1;
        if (hit) m[0x20] = 2;
        break;
    case 2:
        Moby_PlaySound(0, 0, (int)m);
        spawn_proximity_gated_bolts(m);
        spawn_moby_break_fragments(m, 0x736, 1, 0x737, 1, 1, 2);
        spawn_moby_from_placement(m, 0x735);
        DeleteMoby(m);
        break;
    }
}
